import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Link, useNavigate, useParams, useLocation } from 'react-router-dom';
import './styles/global.css';
import './App.css';
// Trails will be generated by AI or fetched from API
import { trails } from './data/trails';
import TrailCard from './components/trails/TrailCard';
import TrailDetail from './components/trails/TrailDetail';
import ItineraryGenerator from './components/itinerary/ItineraryGenerator';
import RoutePlanner from './components/route/RoutePlanner';
import { AuthProvider, useAuth } from './context/AuthContext';
import { loginWithGoogle, logout } from './services/authService';
import { getUserItineraries, getUserActivities, deleteItinerary, logActivity, getUserCheckIns } from './services/dbService';
import { PublicItinerary } from './pages/PublicItinerary';
import SearchBar from './components/search/SearchBar';
import { LanguageSwitcher } from './components/common/LanguageSwitcher';
import { LanguageProvider, useLanguage } from './services/i18n';

// Home Page Component
const HomePage: React.FC = () => {
  const navigate = useNavigate();
  const { t } = useLanguage();
  const [savedTrails, setSavedTrails] = useState<string[]>([]);
  const featuredTrails = trails.slice(0, 4); // Will be empty until AI generates trails

  const toggleSave = (trailId: string) => {
    setSavedTrails(prev =>
      prev.includes(trailId)
        ? prev.filter(id => id !== trailId)
        : [...prev, trailId]
    );
  };

  return (
    <div className="home animate-fadeIn">
      <section className="hero">
        <div className="hero__content animate-slideUp">
          <span className="hero__eyebrow">
            {t('home.eyebrow')}
          </span>
          <h1 className="hero__title">
            {t('home.title')}<br /><span className="highlight">{t('home.title.highlight')}</span>
          </h1>
          <p className="hero__subtitle">
            {t('home.subtitle')}
          </p>
          <div className="hero__cta">
            <Link to="/generator" className="btn btn-primary btn-lg">
              {t('home.create')}
            </Link>
            <Link to="/route" className="btn btn-outline btn-lg">
              {t('home.route')}
            </Link>
          </div>
        </div>

        <div className="hero__features container stagger-children">
          <div className="feature-card">
            <h3>{t('home.feature1.title')}</h3>
            <p>{t('home.feature1.desc')}</p>
          </div>
          <div className="feature-card">
            <h3>{t('home.feature2.title')}</h3>
            <p>{t('home.feature2.desc')}</p>
          </div>
          <div className="feature-card">
            <h3>{t('home.feature3.title')}</h3>
            <p>{t('home.feature3.desc')}</p>
          </div>
        </div>
      </section>

      {featuredTrails.length > 0 && (
        <section className="section container">
          <div className="section-header">
            <h2>{t('home.featured')}</h2>
            <Link to="/route" className="section-link">{t('home.explore')}</Link>
          </div>
          <div className="trails-grid stagger-children">
            {featuredTrails.map((trail) => (
              <div key={trail.id}>
                <TrailCard
                  trail={trail}
                  onClick={() => navigate(`/trails/${trail.id}`)}
                  onSave={() => toggleSave(trail.id)}
                  isSaved={savedTrails.includes(trail.id)}
                />
              </div>
            ))}
          </div>
        </section>
      )}

      <section className="cta-section">
        <div className="container">
          <div className="cta-card">
            <h2>{t('home.cta.title')}</h2>
            <p>{t('home.cta.desc')}</p>
            <Link to="/generator" className="btn btn-primary btn-lg">
              {t('home.cta.button')}
            </Link>
          </div>
        </div>
      </section>
    </div>
  );
};


// Trail Detail Page Wrapper
const TrailDetailPage: React.FC<{ trailId: string }> = ({ trailId }) => {
  const navigate = useNavigate();
  const { t } = useLanguage();
  const [savedTrails, setSavedTrails] = useState<string[]>([]);
  const trail = trails.find(t => t.id === trailId);
  const { user } = useAuth();

  useEffect(() => {
    if (user && trail) {
      logActivity(user.uid, {
        type: 'view',
        title: '查看路線',
        message: `查看了「${trail.title}」的詳細內容`
      });
    }
  }, [user, trail]);

  if (!trail) {
    return (
      <div className="not-found">
        <h2>{t('trail.notFound')}</h2>
        <Link to="/trails" className="btn btn-primary">{t('trail.backToList')}</Link>
      </div>
    );
  }

  const toggleSave = () => {
    setSavedTrails(prev =>
      prev.includes(trailId)
        ? prev.filter(id => id !== trailId)
        : [...prev, trailId]
    );
  };

  return (
    <TrailDetail
      trail={trail}
      onBack={() => navigate('/trails')}
      onSave={toggleSave}
      isSaved={savedTrails.includes(trailId)}
    />
  );
};

// Generator Page Wrapper
const GeneratorPage: React.FC = () => {
  const { t } = useLanguage();
  return (
    <div className="generator-page">
      <header className="page-header">
        <Link to="/" className="back-link">{t('nav.back')}</Link>
      </header>
      <ItineraryGenerator />
    </div>
  );
};

// Route Planner Page Wrapper
const RoutePlannerPage: React.FC = () => {
  const { t } = useLanguage();
  return (
    <div className="route-planner-page">
      <header className="page-header">
        <Link to="/" className="back-link">{t('nav.back')}</Link>
      </header>
      <RoutePlanner />
    </div>
  );
};

// Profile Page Component
const ProfilePage: React.FC = () => {
  const { user, loading } = useAuth();
  const { t } = useLanguage();
  const [savedItineraries, setSavedItineraries] = useState<any[]>([]);
  const [activities, setActivities] = useState<any[]>([]);
  const [checkIns, setCheckIns] = useState<any[]>([]);
  const [activeTab, setActiveTab] = useState<'itineraries' | 'checkins' | 'activity' | 'achievements'>('itineraries');
  const navigate = useNavigate();

  useEffect(() => {
    if (!loading && !user) {
      navigate('/');
    }
    if (user) {
      getUserItineraries(user.uid).then((itineraries) => {
        setSavedItineraries(itineraries);
      });
      getUserActivities(user.uid).then(setActivities);
      getUserCheckIns(user.uid).then(setCheckIns);
    }
  }, [user, loading, navigate]);

  // Search function for itineraries
  const handleSearch = (query: string) => {
    if (!query.trim()) {
      return savedItineraries.map(i => ({
        id: i.id,
        type: 'itinerary' as const,
        title: i.city || t('common.unnamed'),
        subtitle: i.date,
        meta: i.preferences?.categories?.join(', ') || '',
        data: i
      }));
    }

    const lowerQuery = query.toLowerCase();
    const filtered = savedItineraries.filter(i => {
      const city = (i.city || '').toLowerCase();
      const date = (i.date || '').toLowerCase();
      const categories = (i.preferences?.categories || []).join(' ').toLowerCase();
      const theme = (i.preferences?.theme || '').toLowerCase();

      return city.includes(lowerQuery) ||
        date.includes(lowerQuery) ||
        categories.includes(lowerQuery) ||
        theme.includes(lowerQuery);
    });

    return filtered.map(i => ({
      id: i.id,
      type: 'itinerary' as const,
      title: i.city || t('common.unnamed'),
      subtitle: i.date,
      meta: i.preferences?.categories?.join(', ') || '',
      data: i
    }));
  };

  const handleSearchSelect = (result: { id: string; type: string; data?: any }) => {
    if (result.data) {
      handleViewItinerary(result.data);
    }
  };

  const handleDeleteItinerary = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (window.confirm(t('profile.itinerary.delete.confirm'))) {
      try {
        await deleteItinerary(id);
        setSavedItineraries(prev => prev.filter((i: any) => i.id !== id));
        if (user) {
          logActivity(user.uid, {
            type: 'delete',
            title: '刪除行程',
            message: '移除了一項收藏行程'
          });
        }
      } catch (error) {
        alert(t('common.error'));
      }
    }
  };

  const handleViewItinerary = (itinerary: any) => {
    navigate('/generator', { state: { savedItinerary: itinerary } });
  };

  if (loading) return (
    <div className="loading-screen">
      <div className="premium-loader"></div>
      <div className="loading-text">{t('profile.loading')}</div>
    </div>
  );
  if (!user) return null;

  // Derived stats
  const totalItineraries = savedItineraries.length;
  const uniqueCities = new Set(savedItineraries.map(i => i.city)).size;
  const travelerLevel = Math.floor(totalItineraries / 3) + 1;

  return (
    <div className="profile-page animate-fadeIn">
      <header className="profile-header">
        <div className="container">
          <div className="profile-header-content">
            <button onClick={() => navigate(-1)} className="icon-btn back-btn">
              <span>Back</span>
            </button>
            <h1>{t('profile.title')}</h1>
            <button onClick={logout} className="logout-btn-top">{t('nav.logout')}</button>
          </div>
        </div>
      </header>

      <div className="container">
        {/* User Hero Section */}
        <div className="profile-hero">
          <div className="profile-hero-main">
            <div className="avatar-wrapper">
              <img src={user.photoURL || ''} alt={user.displayName || ''} className="profile-avatar" />
              <div className="level-badge">Lv.{travelerLevel}</div>
            </div>
            <div className="profile-info">
              <h2>{user.displayName}</h2>
              <p className="user-email">{user.email}</p>
              <div className="user-tags">
                <span className="user-tag">{t('profile.tag.explorer')}</span>
                <span className="user-tag">{t('profile.tag.foodie')}</span>
              </div>
            </div>
          </div>

          <div className="profile-stats">
            <div className="stat-item">
              <span className="stat-value">{totalItineraries}</span>
              <span className="stat-label">{t('profile.stats.itineraries')}</span>
            </div>
            <div className="stat-divider"></div>
            <div className="stat-item">
              <span className="stat-value">{uniqueCities}</span>
              <span className="stat-label">{t('profile.stats.cities')}</span>
            </div>
            <div className="stat-divider"></div>
            <div className="stat-item">
              <span className="stat-value">{travelerLevel * 120}</span>
              <span className="stat-label">{t('profile.stats.points')}</span>
            </div>
          </div>
        </div>

        {/* Search Bar */}
        <div className="profile-search">
          <SearchBar
            placeholder={t('profile.search.placeholder')}
            onSearch={handleSearch}
            onSelect={handleSearchSelect}
          />
        </div>

        {/* Tab Navigation */}
        <div className="profile-tabs">
          <button
            className={`tab-btn ${activeTab === 'itineraries' ? 'active' : ''}`}
            onClick={() => setActiveTab('itineraries')}
          >
            {t('profile.tab.itineraries')}
          </button>
          <button
            className={`tab-btn ${activeTab === 'checkins' ? 'active' : ''}`}
            onClick={() => setActiveTab('checkins')}
          >
            {t('profile.tab.checkins')}
          </button>
          <button
            className={`tab-btn ${activeTab === 'activity' ? 'active' : ''}`}
            onClick={() => setActiveTab('activity')}
          >
            {t('profile.tab.activity')}
          </button>
          <button
            className={`tab-btn ${activeTab === 'achievements' ? 'active' : ''}`}
            onClick={() => setActiveTab('achievements')}
          >
            {t('profile.tab.achievements')}
          </button>
        </div>

        {/* Tab Content */}
        <div className="tab-content">
          {activeTab === 'itineraries' && (
            <section className="profile-section animate-slideUp">
              {savedItineraries.length === 0 ? (
                <div className="empty-state-card">
                  <p>{t('profile.empty.itineraries')}</p>
                  <button onClick={() => navigate('/generator')} className="btn btn-primary">{t('profile.empty.itineraries.cta')}</button>
                </div>
              ) : (
                <div className="itineraries-grid">
                  {savedItineraries.map(itinerary => (
                    <div key={itinerary.id} className="itinerary-history-card enhanced">
                      <div className="itinerary-card-header">
                        <span className="itinerary-date">{itinerary.date}</span>
                        <span className="itinerary-city">{itinerary.city}</span>
                      </div>
                      <div className="itinerary-card-body">
                        <div className="itinerary-preview-tags">
                          {itinerary.preferences?.categories?.slice(0, 3).map((cat: string) => (
                            <span key={cat} className="preview-tag">{cat}</span>
                          ))}
                        </div>
                        <div className="itinerary-details">
                          <div className="detail-item">
                            <span className="detail-label">{t('profile.itinerary.spots')}：</span>
                            <span className="detail-text">
                              {Object.keys(itinerary.trail || {}).filter(k => itinerary.trail[k]).length} {t('common.unit.count')}
                            </span>
                          </div>
                          <div className="detail-item">
                            <span className="detail-label">{t('profile.itinerary.duration')}：</span>
                            <span className="detail-text">
                              {itinerary.preferences?.duration === 'half' ? t('profile.itinerary.duration.half') :
                                itinerary.preferences?.duration === 'full' ? t('profile.itinerary.duration.full') : t('profile.itinerary.duration.deep')}
                            </span>
                          </div>
                          <div className="detail-item">
                            <span className="detail-label">{t('profile.itinerary.walking')}：</span>
                            <span className="detail-text">
                              {itinerary.preferences?.walking === 'low' ? t('profile.itinerary.walking.low') :
                                itinerary.preferences?.walking === 'high' ? t('profile.itinerary.walking.high') : t('profile.itinerary.walking.medium')}
                            </span>
                          </div>
                        </div>
                        {itinerary.preferences?.theme && (
                          <div className="itinerary-theme-badge">
                            {itinerary.preferences.theme}
                          </div>
                        )}
                      </div>
                      <div className="itinerary-card-footer">
                        <button className="view-btn" onClick={() => handleViewItinerary(itinerary)}>{t('profile.itinerary.view')}</button>
                        <button className="delete-btn-icon" onClick={(e) => handleDeleteItinerary(itinerary.id, e)} title={t('common.delete')}>
                          {t('profile.itinerary.delete')}
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </section>
          )}

          {activeTab === 'checkins' && (
            <section className="profile-section animate-slideUp">
              {checkIns.length === 0 ? (
                <div className="empty-state-card">
                  <p>{t('profile.empty.checkins')}</p>
                  <p className="empty-hint">{t('profile.empty.checkins.hint')}</p>
                </div>
              ) : (
                <div className="checkins-grid">
                  {checkIns.map(checkin => (
                    <div key={checkin.id} className="checkin-card">
                      <div className="checkin-header">
                        <span className="checkin-place">{checkin.placeName}</span>
                        <span className="checkin-rating">{checkin.rating || 5}/5</span>
                      </div>
                      <p className="checkin-address">{checkin.placeAddress}</p>
                      {checkin.note && <p className="checkin-note">「{checkin.note}」</p>}
                      <span className="checkin-time">
                        {checkin.timestamp?.seconds
                          ? new Date(checkin.timestamp.seconds * 1000).toLocaleDateString('zh-TW')
                          : t('common.just.now')}
                      </span>
                    </div>
                  ))}
                </div>
              )}
            </section>
          )}

          {activeTab === 'activity' && (
            <section className="profile-section animate-slideUp">
              {activities.length === 0 ? (
                <div className="empty-state-card">
                  <p>{t('profile.empty.activity')}</p>
                </div>
              ) : (
                <div className="activity-timeline">
                  {activities.map(activity => (
                    <div key={activity.id} className="activity-item">
                      <div className="activity-dot"></div>
                      <div className="activity-info">
                        <span className="activity-time">
                          {activity.timestamp?.toDate ? activity.timestamp.toDate().toLocaleString() : t('common.just.now')}
                        </span>
                        <p><strong>{activity.title}</strong>: {activity.message}</p>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </section>
          )}

          {activeTab === 'achievements' && (
            <section className="profile-section animate-slideUp">
              <div className="achievements-grid">
                <div className="achievement-card earned">
                  <h4>{t('achievement.firstPlan')}</h4>
                  <p>{t('achievement.firstPlan.desc')}</p>
                </div>
                <div className={`achievement-card ${activities.some(a => a.type === 'view') ? 'earned' : 'locked'}`}>
                  <h4>{t('achievement.photographer')}</h4>
                  <p>{t('achievement.photographer.desc')}</p>
                </div>
                <div className={`achievement-card ${totalItineraries >= 5 ? 'earned' : 'locked'}`}>
                  <h4>{t('achievement.planner')}</h4>
                  <p>{t('achievement.planner.desc')}</p>
                </div>
                <div className={`achievement-card ${uniqueCities >= 3 ? 'earned' : 'locked'}`}>
                  <h4>{t('achievement.traveler')}</h4>
                  <p>{t('achievement.traveler.desc')}</p>
                </div>
              </div>
            </section>
          )}
        </div>
      </div>
    </div>
  );
};

// Route Wrapper for Trail Detail
const TrailDetailRoute: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  return <TrailDetailPage trailId={id || ''} />;
};

const Navigation: React.FC = () => {
  const location = useLocation();
  const { user } = useAuth();
  const { t } = useLanguage();
  const isActive = (path: string) => location.pathname === path;

  const handleLogin = async () => {
    try {
      console.log('Starting Google login flow...');
      await loginWithGoogle();
    } catch (error: any) {
      console.error('Login failed:', error);
      if (error.code === 'auth/popup-blocked') {
        alert(t('auth.popupBlocked'));
      } else {
        alert(`${t('auth.loginFailed')}: ${error.message || 'Unknown error'}`);
      }
    }
  };

  return (
    <>
      <nav className="bottom-nav">
        <Link to="/" className={`nav-item ${isActive('/') ? 'active' : ''}`}>
          {t('nav.home')}
        </Link>
        <Link to="/route" className={`nav-item ${isActive('/route') ? 'active' : ''}`}>
          {t('nav.route')}
        </Link>
        <Link to="/generator" className={`nav-item ${isActive('/generator') ? 'active' : ''}`}>
          {t('nav.generator')}
        </Link>
        {user ? (
          <Link to="/profile" className={`nav-item ${isActive('/profile') ? 'active' : ''}`}>
            {t('nav.profile')}
          </Link>
        ) : (
          <button onClick={handleLogin} className="nav-item login-btn">
            {t('nav.login')}
          </button>
        )}
      </nav>
      <div style={{ position: 'fixed', top: 'var(--space-4)', right: 'var(--space-4)', zIndex: 1000 }}>
        <LanguageSwitcher />
      </div>
    </>
  );
};

// Main App Component
const App: React.FC = () => {
  return (
    <LanguageProvider>
      <AuthProvider>
        <Router>
          <div className="app">
            <Routes>
              <Route path="/" element={<HomePage />} />
              <Route path="/trails/:id" element={<TrailDetailRoute />} />
              <Route path="/itinerary/:id" element={<PublicItinerary />} />
              <Route path="/generator" element={<GeneratorPage />} />
              <Route path="/route" element={<RoutePlannerPage />} />
              <Route path="/profile" element={<ProfilePage />} />
            </Routes>
            <Navigation />
          </div>
        </Router>
      </AuthProvider>
    </LanguageProvider>
  );
};

export default App;

